// Key actions to modify in Story 26.2:
// 1. updateNote - trigger indexNote after save
// 2. deleteNote - trigger removeNoteFromIndex after delete
// 3. Add indexStatus to NoteRecord state

export const useNoteStore = create<NoteStoreState>()(
    persist(
        (set, get) => ({
            notes: new Map(),
            notesArray: [],
            activeNoteId: null,
            currentProjectId: null,
            saveStatus: 'idle',  // Extend with indexStatus
            loading: false,
            error: null,
            _hasHydrated: false,
            // ... actions
        }),
        { name: 'note-storage', storage: createDexieStorage() }
    )
);

// Key exports to use:
export async function createIndex(config: IndexConfig): Promise<Orama<OramaSchema>>
export async function indexDocument(projectId: string, document: DocumentSchema): Promise<void>
export async function removeFromIndex(projectId: string, sourceId: string): Promise<void>
export async function searchIndex(projectId: string, query: string, options): Promise<SearchResult[]>
export async function saveIndex(projectId: string, index?: Orama<OramaSchema>): Promise<void>

// Schema: { id, sourceId, content, title, position, embedding?, metadata }

// Key functions to potentially use:
export async function generateEmbedding(text: string, config: EmbeddingConfig): Promise<EmbeddingResult>

// Uses Xenova/all-MiniLM-L6-v2 (384-dim quantized model)
// Has local (WebGPU) and cloud (Gemini) providers
// Story 26.2 should create Web Worker version for non-blocking

async function generateLocalEmbedding(text: string, _modelName?: string): Promise<EmbeddingResult> {
    const { pipeline } = await import('@xenova/transformers');
    const extractor = await pipeline('feature-extraction', 'Xenova/all-MiniLM-L6-v2', {
        quantized: true, // Use Q4 quantized model (~90MB)
    });
    const output = await extractor(text, { pooling: 'mean', normalize: true });
    const embedding = Array.from(output.data as Float32Array);
    return { embedding, provider: 'local', latencyMs };
}

export interface NoteRecord {
    id: string;
    projectId: string;
    title: string;
    emoji?: string;
    blocks: unknown[];  // BlockNote JSON blocks
    parentId?: string;
    isFavorite: boolean;
    order: number;
    isIndexed: boolean;     // <-- Already exists, use for Story 26.2
    indexedAt?: number;     // <-- Already exists
    createdAt: number;
    updatedAt: number;
}

// Add in Story 26.2:
export type NoteIndexStatus = 'pending' | 'indexing' | 'indexed' | 'error';

finding.pattern:
// Web Worker script (note-embedding.worker.ts)
import { pipeline } from '@huggingface/transformers';

class EmbeddingPipeline {
  static instance = null;
  static async getInstance(progress_callback = null) {
    this.instance ??= pipeline('feature-extraction', 'Xenova/all-MiniLM-L6-v2', { progress_callback, quantized: true });
    return this.instance;
  }
}

self.addEventListener('message', async (event) => {
  const { noteId, content } = event.data;
  const extractor = await EmbeddingPipeline.getInstance(x => self.postMessage({ status: 'progress', ...x }));
  const output = await extractor(content, { pooling: 'mean', normalize: true });
  self.postMessage({ status: 'complete', noteId, embedding: Array.from(output.data) });
});

// Extend OramaSchema in src/lib/rag/types.ts for notes:
export interface NoteDocumentSchema {
    id: string;           // noteId-chunk-{index}
    noteId: string;       // Parent note ID
    content: string;      // Plain text chunk
    title: string;        // Note title
    position: number;     // Chunk index
    embedding?: number[]; // 384-dim vector
    metadata: {
        chunkIndex: number;
        totalChunks: number;
    };
}

pattern.code:
const MAX_RETRIES = 3;
const RETRY_DELAYS = [5000, 10000, 20000]; // 5s, 10s, 20s

async function embedWithRetry(noteId: string, content: string): Promise<number[]> {
    for (let attempt = 0; attempt < MAX_RETRIES; attempt++) {
        try {
            return await embedInWorker(noteId, content);
        } catch (error) {
            if (attempt < MAX_RETRIES - 1) {
                await sleep(RETRY_DELAYS[attempt]);
            } else {
                throw error; // Final failure
            }
        }
    }
}

// src/lib/notes/types.ts - extend with full content extraction
export function extractTextFromBlocks(blocks: unknown[]): string {
    const texts: string[] = [];
    for (const block of blocks) {
        if (block.content && Array.isArray(block.content)) {
            for (const item of block.content) {
                if (item.type === 'text' && item.text) {
                    texts.push(item.text);
                }
            }
        }
    }
    return texts.join('\n').trim();
}
